file.content:
    after < cursor <= snapshot；页内 (issuer_did, presentation_id)
    不得重复。空串为零行的合法页。
    """
    if not ndjson:
        return []
    if not ndjson.endswith("\n") or "\r" in ndjson:
        return None
    events: List[Dict[str, Any]] = []
    seen_keys: set = set()
    prev_cursor = after
    for line in ndjson.split("\n")[:-1]:
        if not line:
            return None
        try:
            row = json.loads(line)
        except (json.JSONDecodeError, ValueError):
            return None
        if not isinstance(row, dict):
            return None
        if list(row.keys()) != [
            "cursor",
            "consumption_id",
            "issuer_did",
            "presentation_id",
            "consumed_at",
        ]:
            return None
        cursor = row["cursor"]
        if (
            not isinstance(cursor, int)
            or isinstance(cursor, bool)
            or cursor <= after
            or cursor > snapshot
            or cursor <= prev_cursor
        ):
            return None
        for field in (
            "consumption_id",
            "issuer_did",
            "presentation_id",
            "consumed_at",
        ):
            if not isinstance(row[field], str) or not row[field]:
                return None
        key = (row["issuer_did"], row["presentation_id"])
        if key in seen_keys:
            return None
        seen_keys.add(key)
        prev_cursor = cursor
        events.append(row)
    return events

def _post_trust_presentation_sync(self, tenant: str) -> None:
    # POST /v1/trust/presentation-sync：跨系统外部演示消费历史
    # 同步接收与防重放检查点（验真通过的导出页可靠落盘，不记
    # 审计）。
    # 1) 请求体恰含 manifest（对象）、ndjson（字符串）：非法
    #    JSON/非对象、缺漏或多余字段、类型不符一律 400 且仅
    #    {"error":"请求非法"}；显式空租户头由路由统一判 400，
    #    缺省 default、按租户隔离；
    # 2) 外层合法后沿用外部演示消费清单验真（清单非法 -> 锚点
    #    不可用，本租户同 signer_did/版本含 vp 用途的 active
    #    锚点 -> 签名格式错误 -> 签名校验失败 -> 导出内容不匹
    #    配），任何失败 200 按键序恰返
    #    {"valid":false,"reason":...}，且不写入；
    # 3) NDJSON 须符合既有演示消费 export 协议：cursor 严格递增
    #    且 after<cursor<=snapshot；除同位同内容重放外，新行在
    #    页内或与本租户历史（本地 consume 或他 signer 同步页）
    #    重复 (issuer_did,presentation_id) 均 200 返
    #    {"valid":false,"reason":"导出内容非法"}；
    # 4) 检查点按 (租户, signer_did) 隔离：首次 after=0；同
    #    snapshot 续页 after 等于已存 next_after；追至旧
    #    snapshot 后方可接收更大 snapshot；同位同内容重放 200，
    #    旧页、跳页或同位异内容 409 仅
    #    {"error":"同步游标冲突"}；
    # 5) 首次成功 201、新页 200，响应键序恰为 valid、signer_did、
    #    snapshot、next_after、count；
    # 6) 事件、判重索引与检查点原子持久化，落盘失败回滚并 500
    #    仅 {"error":"存储失败"}；并发同一检查点仅一次推进，
    #    重启保持。
    try:
        data = self._read_json()
        if set(data) != {"manifest", "ndjson"}:
            raise ValidationError("请求非法")
        manifest = data["manifest"]
        ndjson = data["ndjson"]
        if not isinstance(manifest, dict):
            raise ValidationError("请求非法")
        if not isinstance(ndjson, str):
            raise ValidationError("请求非法")
    except (ValidationError, ValueError):
        # ValueError：JSON 内超长十进制整数触发位数上限。
        raise ValidationError("请求非法")

    # 阶段一：沿用演示消费清单验真（清单非法 -> 锚点不可用[vp]
    # -> 签名格式错误 -> 签名校验失败 -> 导出内容不匹配）。
    reason = self._verify_presentation_consumption_manifest_item(
        tenant, manifest, ndjson
    )
    if reason is not None:
        self._send_json(200, {"valid": False, "reason": reason})
        return

    signer_did = manifest["signer_did"]
    snapshot = manifest["snapshot"]
    after = manifest["filters"]["after"]

    # 阶段二：NDJSON 结构、游标窗口与页内重复键。
    events = self._parse_presentation_sync_ndjson(
        ndjson, after, snapshot
    )
    if events is None:
        self._send_json(
            200, {"valid": False, "reason": "导出内容非法"}
        )
        return

    # 阶段三：检查点推进、历史重复键与原子落盘。
    try:
        created, effective_snapshot, next_after, count = (
            store.sync_trust_presentation_consumptions(
                tenant, signer_did, snapshot, after, events
            )
        )
    except ConflictError:
        self._send_error(409, "同步游标冲突")
        return
    except ValidationError:
        self._send_json(
            200, {"valid": False, "reason": "导出内容非法"}
        )
        return
    except StorageError:
        self._send_error(500, "存储失败")
        return
    self._send_json(
        201 if created else 200,
        {
            "valid": True,
            "signer_did": signer_did,
            "snapshot": effective_snapshot,
            "next_after": next_after,
            "count": count,
        },
    )

def _post_trust_presentation_sync_batch(self, tenant: str) -> None:
    # POST /v1/trust/presentation-sync-batch：批量同步跨系统外部
    # 演示消费历史，任何失败都返回 HTTP 200。请求体须恰为
    # {"items": [项...]}，数组限 1–50 项；请求级非法（空体、非法
    # JSON、非对象、键集错、items 非数组/空/超限）一律恰返
    # {"results": [], "reason": "请求非法"}，不写任何状态。
    # 请求级合法时按输入顺序逐项复用单条 presentation-sync 的
    # 完整规则（清单验真、NDJSON 结构、重复键、游标与检查点、
    # 原子落盘），失败不短路：项结构/类型错误收敛为
    # {valid:false,http_status:400,reason:"请求项非法"}；验真/
    # 内容失败沿用单条 200 固定 reason；游标冲突 409“同步游标
    # 冲突”；落盘失败 500“存储失败”且仅回滚本项。失败项键序
    # valid,http_status,reason；成功项键序 valid,http_status,
    # signer_did,snapshot,next_after,count（首次检查点 201，否则
    # 200）。同签名方后项可见前项已提交状态；逐项原子提交，与单
    # 条并发不跳页、不重复推进、不半写，跨重启保持；同步不写审
    # 计。显式空 X-Tenant-ID 在此之前由路由统一判 400。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except Exception:  # noqa: BLE001 请求非法绝不暴露内部细节
        self._send_json(
            200, {"results": [], "reason": "请求非法"}
        )
        return
    data: Any = None
    if raw:
        try:
            data = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError, ValueError):
            # ValueError：JSON 内超长十进制整数触发位数上限。
            data = None
    items = data.get("items") if isinstance(data, dict) else None
    if (
        not isinstance(data, dict)
        or set(data) != {"items"}
        or not isinstance(items, list)
        or not 1 <= len(items) <= 50
    ):
        self._send_json(
            200, {"results": [], "reason": "请求非法"}
        )
        return

    results = [
        self._presentation_sync_batch_item(tenant, item)
        for item in items
    ]
    self._send_json(200, {"results": results})

